package com.vandorlabs.neoforge.ramp;
import com.vandorlabs.ramp.*;
import java.util.*;
import net.minecraft.core.*;
/** Current/next physical reservations, independent of before-image ownership and world publication. */
public final class NativeRampFootprint {
 public record Spec(BlockPos root,Direction facing,int sourceY,int minimumAlong,int length,double low,double high,double start,double end,int treadPixels,boolean elevator,int travel,boolean extend,boolean fast,int interpolation,boolean verticalLayout,boolean moat,List<NativeRampGeometry.Origin> origins) implements NativeRampBeltGeometry.Profile {public Spec{root=root.immutable();origins=List.copyOf(origins);if(!facing.getAxis().isHorizontal()||origins.isEmpty()||origins.size()>128||length<1||length>128||(treadPixels<1||treadPixels>16)||travel<0||travel>2||interpolation<0||interpolation>2||!Double.isFinite(low)||!Double.isFinite(high)||low<0||high>1||low>=high||!Double.isFinite(start)||!Double.isFinite(end)||Math.abs(start)>16||Math.abs(end)>16)throw new IllegalArgumentException("Ramp footprint scalars");var seen=new HashSet<BlockPos>();for(var origin:origins){if(!seen.add(origin.position()))throw new IllegalArgumentException("Duplicate Ramp footprint origin");if(Math.abs((long)origin.position().getX()-root.getX())>64||Math.abs((long)origin.position().getY()-root.getY())>64||Math.abs((long)origin.position().getZ()-root.getZ())>64)throw new IllegalArgumentException("Ramp footprint origin bounds");}}}
 public static Set<BlockPos> cells(Spec spec,double from,double to){if(!Double.isFinite(from)||!Double.isFinite(to)||from<0||from>1||to<0||to>1)throw new IllegalArgumentException("Ramp footprint pose");var result=new HashSet<BlockPos>();var direction=RampGeometry.Direction.valueOf(spec.facing.name());long work=0;
  for(var source:spec.origins){var p=source.position();int row=p.getX()*spec.facing.getStepX()+p.getZ()*spec.facing.getStepZ()-spec.minimumAlong;
   if(spec.moat){for(var nativeShape:source.shapes()){var shape=new RampGeometry.Box(nativeShape.minX,nativeShape.minY,nativeShape.minZ,nativeShape.maxX,nativeShape.maxY,nativeShape.maxZ);for(var piece:MoatGeometry.pieces(direction,shape,spec.treadPixels)){if(++work>131072)throw new IllegalArgumentException("Ramp footprint work budget");add(result,spec.root,MoatGeometry.sweep(direction,spec.sourceY,spec.length,spec.treadPixels,spec.start,spec.end,from,to,spec.fast,spec.interpolation,p.getY(),MoatGeometry.step(direction,piece,spec.treadPixels),MoatGeometry.world(piece,p.getX(),p.getY(),p.getZ()),MoatGeometry.world(shape,p.getX(),p.getY(),p.getZ())));}}continue;}
   for(int step=0;step<(spec.elevator?1:ControllerPlatform.treadCount(spec.treadPixels));step++){if(++work>131072)throw new IllegalArgumentException("Ramp footprint work budget");var box=spec.verticalLayout?VerticalRampGeometry.sweep(direction,p.getX(),p.getY(),p.getZ(),spec.low,spec.high,spec.sourceY,spec.length,spec.treadPixels,step,spec.start,spec.end,from,to,spec.elevator,spec.travel,spec.extend,spec.fast,spec.interpolation,false):RampGeometry.movingTread(direction,p.getX(),p.getY(),p.getZ(),spec.low,spec.high,row,spec.length,spec.start,spec.end,spec.treadPixels,step,from,to,spec.elevator,spec.travel,spec.extend,spec.fast,spec.interpolation);add(result,spec.root,box);}
  }
  if(spec.moat)result.remove(spec.root);return Set.copyOf(result);
 }
 static void add(Set<BlockPos> result,BlockPos root,RampGeometry.Box box){if(!Double.isFinite(box.minX)||!Double.isFinite(box.minY)||!Double.isFinite(box.minZ)||!Double.isFinite(box.maxX)||!Double.isFinite(box.maxY)||!Double.isFinite(box.maxZ))throw new IllegalArgumentException("Nonfinite Ramp footprint");int x0=(int)Math.floor(box.minX+1e-8),y0=(int)Math.floor(box.minY+1e-8),z0=(int)Math.floor(box.minZ+1e-8),x1=(int)Math.ceil(box.maxX-1e-8),y1=(int)Math.ceil(box.maxY-1e-8),z1=(int)Math.ceil(box.maxZ-1e-8);if(Math.abs((long)x0-root.getX())>64||Math.abs((long)y0-root.getY())>64||Math.abs((long)z0-root.getZ())>64||Math.abs((long)x1-root.getX())>65||Math.abs((long)y1-root.getY())>65||Math.abs((long)z1-root.getZ())>65)throw new IllegalArgumentException("Ramp footprint coordinate bounds");for(int x=x0;x<x1;x++)for(int y=y0;y<y1;y++)for(int z=z0;z<z1;z++){result.add(new BlockPos(x,y,z));if(result.size()>8192)throw new IllegalArgumentException("Ramp footprint cell budget");}}
 private NativeRampFootprint(){}
}
